CREATE TABLE IF NOT EXISTS worlds(world text PRIMARY KEY, hostname text NOT NULL, published_at timestamptz, conquest_checked_at timestamptz, imported_at timestamptz);
CREATE TABLE IF NOT EXISTS import_groups(world text NOT NULL, captured_at timestamptz NOT NULL, kind text NOT NULL, status text NOT NULL, provenance text NOT NULL, manifest jsonb, error text, imported_at timestamptz, PRIMARY KEY(world,captured_at,kind));
CREATE TABLE IF NOT EXISTS source_objects(object_key text PRIMARY KEY, world text NOT NULL, captured_at timestamptz NOT NULL, sha256 text NOT NULL, verified boolean NOT NULL, size_bytes bigint NOT NULL);
CREATE TABLE IF NOT EXISTS manifests(world text NOT NULL, captured_at timestamptz NOT NULL, kind text NOT NULL, content_hash text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(world,captured_at,kind,content_hash));
CREATE TABLE IF NOT EXISTS player_history(world text NOT NULL, captured_at timestamptz NOT NULL, id integer NOT NULL, name text NOT NULL, tribe integer NOT NULL, villages integer NOT NULL, points bigint NOT NULL, rank integer NOT NULL, attack bigint, defense bigint, support bigint, "all" bigint, PRIMARY KEY(world,captured_at,id)) PARTITION BY RANGE(captured_at);
CREATE INDEX IF NOT EXISTS player_history_world_id_captured_at_idx ON player_history(world,id,captured_at DESC);
CREATE TABLE IF NOT EXISTS village_history(world text NOT NULL, captured_at timestamptz NOT NULL, id integer NOT NULL, name text NOT NULL, owner integer NOT NULL, x integer NOT NULL, y integer NOT NULL, points bigint NOT NULL, rank integer NOT NULL, PRIMARY KEY(world,captured_at,id)) PARTITION BY RANGE(captured_at);
CREATE INDEX IF NOT EXISTS village_history_world_owner_captured_at_idx ON village_history(world,owner,captured_at);
CREATE INDEX IF NOT EXISTS village_history_world_captured_at_x_y_idx ON village_history(world,captured_at,x,y);
CREATE TABLE IF NOT EXISTS tribe_history(world text NOT NULL, captured_at timestamptz NOT NULL, id integer NOT NULL, name text NOT NULL, tag text NOT NULL, members integer NOT NULL, villages integer NOT NULL, points bigint NOT NULL, all_points bigint NOT NULL, rank integer NOT NULL, attack bigint, defense bigint, "all" bigint, PRIMARY KEY(world,captured_at,id)) PARTITION BY RANGE(captured_at);
CREATE TABLE IF NOT EXISTS conquests(world text NOT NULL, event_id text NOT NULL, village_id integer NOT NULL, occurred_at timestamptz NOT NULL, new_owner_id integer NOT NULL, old_owner_id integer NOT NULL, PRIMARY KEY(world,event_id));
CREATE INDEX IF NOT EXISTS conquests_world_new_owner_id_occurred_at_idx ON conquests(world,new_owner_id,occurred_at);
CREATE INDEX IF NOT EXISTS conquests_world_old_owner_id_occurred_at_idx ON conquests(world,old_owner_id,occurred_at);
CREATE INDEX IF NOT EXISTS conquests_world_village_id_occurred_at_idx ON conquests(world,village_id,occurred_at);
CREATE TABLE IF NOT EXISTS world_config(world text NOT NULL, captured_at timestamptz NOT NULL, dataset text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(world,captured_at,dataset));
CREATE TABLE IF NOT EXISTS player_daily(world text NOT NULL, day date NOT NULL, id integer NOT NULL, captured_at timestamptz NOT NULL, points bigint NOT NULL, villages integer NOT NULL, attack bigint, defense bigint, support bigint, "all" bigint, PRIMARY KEY(world,day,id));
CREATE TABLE IF NOT EXISTS annotations(owner_email text NOT NULL, world text NOT NULL, player_id integer NOT NULL, relationship text NOT NULL DEFAULT 'unknown' CHECK(relationship IN ('unknown','friendly','neutral','hostile')), watched boolean NOT NULL DEFAULT false, note text NOT NULL DEFAULT '', PRIMARY KEY(owner_email,world,player_id));
CREATE TABLE IF NOT EXISTS preferences(owner_email text PRIMARY KEY, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS importer_runs(id bigserial PRIMARY KEY, world text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, status text NOT NULL DEFAULT 'running', error text);
